    internal static ScenarioSpec Scenario(string scenarioId) =>
        Scenarios.Single(x => x.ScenarioId == scenarioId);

    internal static IReadOnlyList<SubcaseSpec> SubcasesFor(string scenarioId) =>
        Subcases.Where(x => x.ScenarioId == scenarioId).ToArray();

    internal static IReadOnlyList<SelectorSpec> SelectorsFor(string scenarioId) =>
        Selectors.Where(x => x.ComponentId.StartsWith(scenarioId + ":", StringComparison.Ordinal)).ToArray();

    internal static IReadOnlyList<string> RequiredAssertionIds(string scenarioId)
    {
        var scenario = Scenario(scenarioId);
        var required = new List<string>
        {
            scenarioId + ":action-correlated",
            scenarioId + ":terminal-exact",
            scenarioId + ":cleanup-lease"
        };
        if (scenario.SqlState.Length != 0) required.Add(scenarioId + ":sqlstate-exact");
        if (scenario.ErrorCode.Length != 0) required.Add(scenarioId + ":code-exact");
        if (scenario.DatabaseObject.Length != 0) required.Add(scenarioId + ":object-exact");
        required.AddRange(SelectorsFor(scenarioId).Select(x => x.ComponentId));
        return required;
    }

    internal static string ComputedSha256
    {
        get
        {
            var lines = new[] { $"V|{Version}|{FormulaVersion}|{EvidenceSchemaVersion}|{ReaderContractVersion}|{AdapterVersion}|{MappingVersion}" }
                .Concat(Scenarios.OrderBy(x => x.ScenarioId, StringComparer.Ordinal)
                .Select(x => $"S|{x.ScenarioId}|{x.ExpectedOutcome}|{x.SqlState}|{x.ErrorCode}|{x.DatabaseObject}")
                .Concat(Subcases.OrderBy(x => x.SubcaseId, StringComparer.Ordinal)
                    .Select(x => $"U|{x.ScenarioId}|{x.SubcaseId}|{x.PreparationId:D}|{x.AttemptId:D}|{x.EvidenceId:D}|{x.ExpectedResultId:D}|{x.ExpectedOutcome}|{x.ActionId}"))
                .Concat(Selectors.OrderBy(x => x.ComponentId, StringComparer.Ordinal)
                    .Select(x => $"C|{x.ComponentId}|{x.SelectorName}|{x.ValueType}|{x.ReaderId}|{x.Source}|{x.Scope}|{x.Cardinality}|{x.NullSemantics}|{x.Stage}|{x.Operator}|{x.Expected}|{x.Reducer}|{x.RawFactPath}|{x.MappingId}")));
            var canonical = string.Join('\n', lines);
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        }
    }

    internal static void Validate()
    {
        if (Scenarios.Length != ExpectedScenarioCount || Subcases.Length != ExpectedSubcaseCount ||
            Selectors.Length != ExpectedFormulaTermCount)
            throw new InvalidOperationException("Frozen oracle count mismatch.");
        if (Scenarios.Select(x => x.ScenarioId).Distinct(StringComparer.Ordinal).Count() != ExpectedScenarioCount ||
            Subcases.Select(x => x.SubcaseId).Distinct(StringComparer.Ordinal).Count() != ExpectedSubcaseCount ||
            Selectors.Select(x => x.ComponentId).Distinct(StringComparer.Ordinal).Count() != ExpectedFormulaTermCount)
            throw new InvalidOperationException("Frozen oracle identities are not unique.");
        if (Subcases.SelectMany(x => new[] { x.PreparationId, x.AttemptId, x.EvidenceId, x.ExpectedResultId }).Any(x => x == Guid.Empty) ||
            Subcases.Select(x => x.PreparationId).Distinct().Count() != ExpectedSubcaseCount ||
            Subcases.Select(x => x.AttemptId).Distinct().Count() != ExpectedSubcaseCount ||
            Subcases.Select(x => x.EvidenceId).Distinct().Count() != ExpectedSubcaseCount ||
            Subcases.Select(x => x.ExpectedResultId).Distinct().Count() != ExpectedSubcaseCount)
            throw new InvalidOperationException("Every subcase requires unique preparation, attempt, evidence and expected-result identities.");
        if (Scenarios.Any(s => SubcasesFor(s.ScenarioId).Count == 0) ||
            Selectors.Any(x => Scenarios.All(s => !x.ComponentId.StartsWith(s.ScenarioId + ":", StringComparison.Ordinal)) ||
                x.SelectorName.Length == 0 || x.ValueType.Length == 0 || x.ReaderId.Length == 0 ||
                x.Source.Length == 0 || x.Scope.Length == 0 || x.Cardinality.Length == 0 ||
                x.NullSemantics != "missing-or-null=reject" || x.Stage.Length == 0 ||
                x.Operator.Length == 0 || x.Reducer.Length == 0))
            throw new InvalidOperationException("Frozen oracle selector contract is incomplete.");
        if (!string.Equals(ComputedSha256, ExpectedSha256, StringComparison.Ordinal))
            throw new InvalidOperationException($"Frozen oracle SHA-256 mismatch: {ComputedSha256}.");
    }

    internal sealed record ScenarioSpec(string ScenarioId, string ExpectedOutcome, string SqlState,
        string ErrorCode, string DatabaseObject);
    internal sealed record SubcaseSpec(string ScenarioId, string SubcaseId, Guid PreparationId,
        Guid AttemptId, Guid EvidenceId, Guid ExpectedResultId, string ExpectedOutcome, string ActionId);
    internal sealed record SelectorSpec(string ComponentId, string SelectorName, string ValueType,
        string ReaderId, string Source, string Scope, string Cardinality, string NullSemantics,
        string Stage, string Operator, string Expected, string Reducer)
    {
        internal string RawFactPath => "facts." + SelectorName;
        internal string MappingId => MappingVersion + ":" + ComponentId + ":" + ReaderId;
    }
}
